/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },

    Init() {

        this.freeGlow = cc.find("B_Coin_Glow", this.node.parent);
        this.freeCoin = cc.find("coins", this.freeGlow);
        this.freeNode = cc.find("free_node", this.node);
        this.freeEachCoin = cc.find("fg_count_board/coins", this.freeNode);
        this.freeTimes = cc.find("count_board/times", this.freeNode);
        // this.freeBjGlow = cc.find("spr_bg_free/bj_glow", this.node.parent);
        this._freeCoins = 0;

        this._super();

        // 解锁条
        let spine = cc.find("LMSlots_PrizePool_1/prizePool_Grand/spine", this.node.parent).getComponent(sp.Skeleton);
        let deskInfo = cc.vv.gameData.getDeskInfo();

        if (deskInfo.needbet <= deskInfo.currmult) {

            spine.setAnimation(0, "Grand_unlock", false);
        } else {

            spine.setAnimation(0, "Grand_lock_idle", true);
        }

        // 进度条
        this.updateCollectProgress(deskInfo.collectGame);
    },

    //点击旋转按钮调用
    StartMove: function () {
        if (cc.vv.gameData.IsBonusGame()) {
            return;
        }

        this._super();

        Global.SlotsSoundMgr.playNormalBgm();

        if (cc.vv.gameData.isInFreeGame()) {
            this.freeTimes.getComponent(cc.Label).string = (cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime())
                + "/" + cc.vv.gameData.GetTotalFree();
        }
    },

    StopMove() {
        if (cc.vv.gameData.IsBonusGame()) {
            cc.vv.gameData.GetBonusScript().StopMove();
        } else {
            this._super();
        }
    },

    async ReconnectShow() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        let rest = cc.vv.gameData.GetFreeTime();
        if (deskInfo.collectGame.state !== 1) {
            this._bottomScript.ShowBtnsByState("moveing_1");
            this.clearCollectProgress();
            cc.vv.gameData.GetBonusScript().startBonusGame(deskInfo.collectGame);
        } else {
            if (rest) {
                this._bottomScript.ShowBtnsByState("moveing_1");
                this.ShowGameview(true);
                // this.freeBjGlow.active = false;
                Global.SlotsSoundMgr.stopBgm();
                Global.SlotsSoundMgr.playBgm("fgbgm");
                this.freeEachCoin.getComponent(cc.Label).string = Global.formatNumShort(deskInfo.freeGameInfo.baseCoin);
                this._freeCoins = deskInfo.freeGameInfo.totalCoin;
                this.freeCoin.getComponent(cc.Label).string = Global.formatNumShort(this._freeCoins, 0);
                this.CanDoNextRound()
            } else {
                this.ShowGameview(false);
                this.CanDoNextRound()
            }
        }

    },

    async onMsgSpine(msg) {
        if (cc.vv.gameData.IsBonusGame()) {
            cc.vv.gameData.GetBonusScript().onMsgSpine(msg)
        } else {
            this._super(msg);
            if (msg.collectGame) {
                cc.vv.gameData.setCollectGame(msg.collectGame);
            }
        }
    },

    SetSlotsResult: function (cards) {
        let acRow = cards.length / this._col;
        let reelResults = [];
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow);
            let col = i % this._col;
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {};
                res.sid = cards[i]; //符号id
                if (cards[i] === this._cfg.scatterId) {
                    for (let info of this._gameInfo.scatterInfo) {
                        if (info.idx === (i + 1)) {
                            res.data = info;
                            break;
                        }
                    }
                }
                if (!reelResults[col]) reelResults[col] = [];
                reelResults[col].unshift(res);
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //检查进入免费
    CheckEnterFreeGame: function () {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === cc.vv.gameData.GetTotalFree();
    },

    CheckExtraFreeGame() {
        return !!(this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0);
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    async ShowWinTrace() {
        this._super();
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        await this.collectWilds();

        if (cc.vv.gameData.isInFreeGame()) {
            await this.collectFreeCoins();
        }

        this.ShowWinTrace();

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async () => {
            if (this._gameInfo.collectGame.state === 2) {
                await this.triggerBonusGame();
            }
            if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else if (this.CheckExtraFreeGame()) {
                this.triggerExtraFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    this.CanDoNextRound();
                }
            }
        });
    },

    async triggerBonusGame() {
        this.cutScene();

        await cc.vv.gameData.awaitTime(2);

        this.clearCollectProgress();
        await cc.vv.gameData.GetBonusScript().startBonusGame(this._gameInfo.collectGame);
    },

    cutScene() {
        Global.SlotsSoundMgr.playEffect("transition");
        let transition = cc.find("transition", this.node.parent);
        transition.active = true;
        transition.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        transition.getComponent(sp.Skeleton).setCompleteListener(()=>{
            transition.getComponent(sp.Skeleton).setCompleteListener(null);
            transition.active = false;
        });
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._super(bFree);
        this.freeGlow.active = bFree;
        this.freeNode.active = bFree;
        cc.find("role", this.node.parent).active = !bFree;
        cc.find("info_board", this.node.parent).active = !bFree;
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");
        Global.SlotsSoundMgr.playEffect("triggering");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        // 触发免费游戏
        await cc.vv.gameData.awaitTime(1);

        this.ShowGameview(true);
        this._freeCoins = 0;
        this.freeEachCoin.getComponent(cc.Label).string = Global.formatNumShort(this._gameInfo.freeGameInfo.baseCoin, 0);
        this.freeTimes.getComponent(cc.Label).string = "1/5";
        this.freeCoin.getComponent(cc.Label).string = "";
        // this.freeBjGlow.active = false;
        await this.popFreeDialog();

        await cc.vv.gameData.awaitTime(1);

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("fgbgm");
        this.CanDoNextRound();
    },

    async triggerExtraFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        await this.popExtraFreeDialog();

        this.CanDoNextRound();
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        await this.popFreeResultDialog();

        this.ShowGameview(false);

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

    popFreeDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("fg_trigger");
            let free_dialog = cc.find("dialog_node", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("common_enter_node", free_dialog);
            dialog.active = true;
            dialog.scale = 0;

            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let coins = cc.find("title/coins", dialog);
            coins.getComponent(cc.Label).string = Global.formatNumShort(this._gameInfo.freeGameInfo.baseCoin);

            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();
        });
    },

    popExtraFreeDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("add1spin");
            Global.SlotsSoundMgr.playEffect("fg_trigger");

            let free_dialog = cc.find("dialog_node", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("extra_node", free_dialog);
            dialog.active = true;
            dialog.scale = 0;

            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let title = cc.find("title", dialog);
            if (this._gameInfo.freeResult.freeInfo.freeCnt > 1) {
                title.getComponent("ImgSwitchCmp").setIndex(1);
            } else {
                title.getComponent("ImgSwitchCmp").setIndex(0);
            }

            let times = cc.find("title/times", dialog);
            times.getComponent(cc.Label).string = "+" + this._gameInfo.freeResult.freeInfo.freeCnt;

            await cc.vv.gameData.awaitTime(1);

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(() => {
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();
        });
    },

    popFreeResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("fgend");

            let free_dialog = cc.find("dialog_node", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("result_node", free_dialog);
            dialog.active = true;
            dialog.scale = 0;
            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            cc.find("coin", dialog).getComponent(cc.Label).string =
                Global.FormatNumToComma(cc.vv.gameData.GetGameTotalFreeWin());

            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();
        })
    },

    // //根据服务端序号获取本地的symbol
    // GetSymbolByIdx: function (idx) {
    //     this._super(idx);
    // },

    async updateCollectProgress(collectGame) {

    },


    clearCollectProgress() {

    },

    async collectWilds() {
        if (this._gameInfo.wildIdxs && this._gameInfo.wildIdxs.length > 0) {
            for (let i = 0; i < this._gameInfo.wildIdxs.length; i++) {
                let symbol = this.GetSymbolByIdx(this._gameInfo.wildIdxs[i]);
                if (symbol) {
                    symbol.playStopAnimation();

                    await cc.vv.gameData.awaitTime(1);

                    symbol.ShowNormal();
                }
            }
        }
    },

    async collectFreeCoins() {
        if (this._gameInfo.scatterInfo && this._gameInfo.scatterInfo.length > 0) {
            for (let i = 0; i < this._gameInfo.scatterInfo.length; i++) {
                let info = this._gameInfo.scatterInfo[i];
                let symbol = this.GetSymbolByIdx(info.idx);
                if (symbol) {
                    symbol.playFreeAppearAnimation();

                    this._freeCoins += this._gameInfo.freeGameInfo.baseCoin;
                    Global.SlotsSoundMgr.playEffect("scatr_fg");
                    let particle = cc.instantiate(cc.find("particle_star", this.node.parent));
                    particle.active = true;
                    particle.parent = this.node.parent;
                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    particle.position = startPos;
                    let endPos = this.freeGlow.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            this.freeCoin.getComponent(cc.Label).string = Global.formatNumShort(this._freeCoins);
                            // this.freeBjGlow.active = true;
                            // this.freeBjGlow.getComponent(sp.Skeleton).setAnimation(0, "fg_glow", false);
                            // this.freeBjGlow.getComponent(sp.Skeleton).setCompleteListener(()=>{
                            //     this.freeBjGlow.getComponent(sp.Skeleton).setCompleteListener(null);
                            //     this.freeBjGlow.active = false;
                            // });
                        })
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(0.7);
                }
            }

            for (let i = 0; i < this._gameInfo.scatterInfo.length; i++) {
                let info = this._gameInfo.scatterInfo[i];
                let symbol = this.GetSymbolByIdx(info.idx);
                if (symbol) {
                    symbol.playFreeWinAnimation();
                }
            }

            await cc.vv.gameData.awaitTime(0.5);
        }
    },
});