cc.Class({
    extends: require("LMSlots_PrizePool_Base"),
    properties: {

    },

    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit) {
        if (node) {
            let spine = cc.find("spine", node).getComponent(sp.Skeleton);

            if (bLock) {
                if (bInit) {
                    spine.setAnimation(0, "Grand_lock_idle", true);
                } else {
                    spine.clearTracks();
                    spine.setToSetupPose();
                    spine.setAnimation(0, "Grand_lock", false);
                    spine.addAnimation(0, "Grand_lock_idle", true);
                }
            } else {
                if (bInit) {
                    spine.setAnimation(0, "Grand_unlock", true);
                } else {
                    spine.setAnimation(0, "Grand_unlock", false);
                }
            }
        }
    },
});