/**
 * @description
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _exitCallBack:null,

        _curTimes:3,   // 当前剩余次数
        _subGameData: null,
        _canSelect: false,
        _coinNum: 0,
        _yellowCoin: 0,
        _greenCoin: 0,
        _remainTimes: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this.initBonusNode();

        this._slotsScript = this._bonus_slots.addComponent("JapaneseSinger_BonusSlots");

        this.initBonusUI();
    },

    // 初始化节点
    initBonusNode(){
        this._bg_bonus = cc.find("safe_node/spr_bg_bonus", this.node);
        this.bianpao = cc.find("safe_node/role", this.node);
        this._normal_slots = cc.find("safe_node/slots", this.node);
        this._bonus_slots = cc.find("safe_node/bonus_slots", this.node);
        this._topAniNode = cc.find("top_ani",this._bonus_slots);
        this._node_reels = cc.find("reels", this._bonus_slots);
        this.select_root = cc.find("select_root", this._bonus_slots);
        this.gold_coin = cc.find("bg_count_board_yellow/coin", this._bonus_slots);
        this.gold_spine = cc.find("bg_count_board_yellow/spine", this._bonus_slots);
        this.green_coin = cc.find("bg_count_board_green/coin", this._bonus_slots);
        this.green_spine = cc.find("bg_count_board_green/spine", this._bonus_slots);
        this.pick_title = cc.find("count_board/pick_title", this._bonus_slots);
        this.times_title = cc.find("count_board/times_title", this._bonus_slots);
        this.remain_times = cc.find("count_board/times", this._bonus_slots);
        this.coin_num = cc.find("B_Coin_Glow/coins", this._bg_bonus);
        this.bonus_win = cc.find("bonus_win", this._bonus_slots);
        this.bonus_win_coin = cc.find("coin", this.bonus_win);
        this.bonus_win_spine = cc.find("spine", this.bonus_win);
        this.add_spin_spine = cc.find("count_board/spine", this._bonus_slots);
        this.bj_glow = cc.find("bj_glow", this._bg_bonus);
    },

    // 初始化节点状态
    initBonusUI(){
        this._bg_bonus.active = false;
        this._normal_slots.active = true;
        this._bonus_slots.active = false;
        this.bianpao.active = true;
        cc.find("safe_node/info_board", this.node).active = true;
    },


    // 触发
    async startBonusGame(collectGame){
        return new Promise(async (success)=>{
            this._exitCallBack = success;

            this.bj_glow.active = false;

            cc.vv.gameData.SetIsBonusGame(true);

            this.bianpao.active = false;
            cc.find("safe_node/info_board", this.node).active = false;
            this._bg_bonus.active = true;
            this._normal_slots.active = false;
            this._bonus_slots.active = true;

            this.bonus_win.active = false;
            this.remain_times.parent.active = true;
            this.gold_coin.parent.active = true;
            this.green_coin.parent.active = true;

            this._coinNum = 0;
            this._yellowCoin = 0;
            this._greenCoin = 0;

            this._remainTimes = collectGame.gameInfo.restCnt;
            this.updateRemainTimes();

            this._slotsScript.Init();
            this._slotsScript.reconnectInitSymbol();

            if (collectGame.state === 2) {
                Global.SlotsSoundMgr.stopBgm();
                Global.SlotsSoundMgr.playBgm("sgbgm");
                this._canSelect = true;
                this.select_root.active = true;
                for (let i = 0; i < 15; i++) {
                    let item = cc.find("item_" + (i + 1), this.select_root);
                    item.off(cc.Node.EventType.TOUCH_END);
                    let info = collectGame.gameInfo.items[i];
                    if (info.empty) {
                        item.active = true;
                        cc.find("spine", item).getComponent(sp.Skeleton).setAnimation(0, "PickOne_idle", true);
                        item.on(cc.Node.EventType.TOUCH_END, async ()=>{
                            if (!this._canSelect) {
                                return;
                            }
                            Global.SlotsSoundMgr.playEffect("pickone");
                            this._canSelect = false;
                            item.off(cc.Node.EventType.TOUCH_END);

                            let req = {rtype:1, choiceId: (i + 1)};
                            let result = await cc.vv.gameData.reqSubGame(req);
                            if (result.code === 200) {
                                let choiceId = result.data.choiceId;
                                cc.vv.gameData.setCollectGame(result.data.collectGame);
                                let selectItem = cc.find("item_" + choiceId, this.select_root);
                                let selectInfo = result.data.collectGame.gameInfo.items[choiceId - 1];
                                let spine = cc.find("spine", selectItem).getComponent(sp.Skeleton);
                                spine.setAnimation(0, "PickOne_click", false);

                                this._coinNum++;
                                this.coin_num.getComponent(cc.Label).string = this._coinNum;

                                this._remainTimes = result.data.collectGame.gameInfo.restCnt;
                                this.updateRemainTimes();

                                let safe_node = cc.find("safe_node", this.node);
                                let particle = cc.instantiate(cc.find("particle_dian", safe_node));
                                particle.active = true;
                                particle.parent = safe_node;
                                let startPos = selectItem.convertToWorldSpaceAR(cc.v2(0, 0));
                                startPos = safe_node.convertToNodeSpaceAR(startPos);
                                particle.position = startPos;
                                let endPos = this.gold_coin.convertToWorldSpaceAR(cc.v2(0, 0));
                                endPos = safe_node.convertToNodeSpaceAR(endPos);
                                this._yellowCoin += selectInfo.coin;
                                this._greenCoin += selectInfo.coin;
                                Global.SlotsSoundMgr.playEffect("fg_triggerfly");
                                cc.tween(particle)
                                    .to(0.5, {position: endPos})
                                    .call(()=>{
                                        this.gold_spine.active = true;
                                        this.gold_spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                                        this.gold_spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                            this.gold_spine.getComponent(sp.Skeleton).setCompleteListener(null);
                                            this.gold_spine.active = false;
                                        });
                                        this.updateCoin();
                                    })
                                    .removeSelf()
                                    .start();

                                await cc.vv.gameData.awaitTime(0.3);

                                let symbol = this._slotsScript.GetSymbolByIdx(choiceId);
                                if (symbol) {
                                    symbol.ShowById(cc.vv.gameData.getGameCfg().scatterId, selectInfo);
                                    symbol.playBonusAppearAnimation();
                                }

                                await cc.vv.gameData.awaitTime(0.5);

                                if (result.data.collectGame.state === 3) {
                                    await this.popBonusEnterDialog();

                                    for (let j = 0; j < 15; j++) {
                                        cc.find("item_" + (j + 1), this.select_root).active = false;
                                    }


                                    this.reqSpin();
                                } else {
                                    this._canSelect = true;
                                }
                            }
                        });
                    } else {
                        this._coinNum++;
                        item.active = false;
                        let symbol = this._slotsScript.GetSymbolByIdx(i + 1);
                        if (symbol) {
                            symbol.showBonus();
                        }
                        this._yellowCoin += info.coin;
                        this._greenCoin += info.coin;
                    }
                }

                this.coin_num.getComponent(cc.Label).string = this._coinNum;
                this.updateCoin();
            } else if (collectGame.state === 3) {
                for (let j = 0; j < 15; j++) {
                    cc.find("item_" + (j + 1), this.select_root).active = false;
                }

                for (let item of collectGame.gameInfo.items) {
                    if (!item.empty) {
                        this._coinNum++;
                    }
                }
                this._yellowCoin = collectGame.gameInfo.baseCoin;
                this._greenCoin = collectGame.gameInfo.fullCoin;
                this.updateCoin();

                await cc.vv.gameData.awaitTime(0.5);

                this.reqSpin();
            }
        })

    },

    playBjGlow() {
        this.bj_glow.active = true;
        this.bj_glow.getComponent(sp.Skeleton).setAnimation(0, "bg_glow", false);
        this.bj_glow.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this.bj_glow.getComponent(sp.Skeleton).setCompleteListener(null);
            this.bj_glow.active = false;
        });
    },

    popBonusEnterDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("bgbgm");
            Global.SlotsSoundMgr.playEffect("fgend");

            let free_dialog = cc.find("safe_node/dialog_node", this.node);
            free_dialog.active = true;

            let dialog = cc.find("bonus_enter_node", free_dialog);
            dialog.active = true;
            dialog.scale = 0;
            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            cc.find("coin", dialog).getComponent(cc.Label).string = Global.formatNumShort(this._yellowCoin, 0);

            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();
        })
    },

    popBonusResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.playEffect("bgend");

            let free_dialog = cc.find("safe_node/dialog_node", this.node);
            free_dialog.active = true;

            let dialog = cc.find("bonus_result_node", free_dialog);
            dialog.active = true;
            dialog.scale = 0;
            cc.tween(dialog)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            cc.find("coin", dialog).getComponent(cc.Label).string =
                Global.FormatNumToComma(cc.vv.gameData.getCollectGame().gameInfo.winCoin);

            await cc.vv.gameData.awaitTime(1.5);

            cc.tween(dialog)
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    free_dialog.active = false;
                    dialog.active = false;
                    success();
                })
                .start();
        })
    },

    updateCoin() {
        this.gold_coin.getComponent(cc.Label).string = Global.formatNumShort(this._yellowCoin, 0);
        this.green_coin.getComponent(cc.Label).string = Global.formatNumShort(this._greenCoin, 0);
    },

    updateRemainTimes() {
        let collectGame = cc.vv.gameData.getCollectGame();
        if (this._remainTimes < 0) {
            this._remainTimes = 0;
        }
        if (collectGame.state === 2) {
            this.pick_title.active = true;
            this.times_title.active = false;
            if (this._remainTimes <= 1) {
                this.pick_title.getComponent("ImgSwitchCmp").setIndex(0);
            } else {
                this.pick_title.getComponent("ImgSwitchCmp").setIndex(1);
            }

        } else if (collectGame.state === 3) {
            this.pick_title.active = false;
            this.times_title.active = true;
            if (this._remainTimes <= 1) {
                this.times_title.getComponent("ImgSwitchCmp").setIndex(0);
            } else {
                this.times_title.getComponent("ImgSwitchCmp").setIndex(1);
            }
        }
        this.remain_times.getComponent(cc.Label).string = this._remainTimes;
    },


    exitBonusGame(){
        this._slotsScript.ClearAllTopShow();
        cc.vv.gameData.GetSlotsScript().clearCollectProgress();
        this.initBonusUI();
        cc.vv.gameData.SetIsBonusGame(false);
    },

    //点击停止按钮调用
    StopMove:function(){
        this._slotsScript.StopMove();
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        let safe_node = cc.find("safe_node", this.node);
        let collectGame = cc.vv.gameData.getCollectGame();
        for (let i = 0; i < this._subGameData.idxs.length; i++) {
            let idx = this._subGameData.idxs[i];
            let item = collectGame.gameInfo.items[i];
            if (item.type === 4) {
                let symbol = this._slotsScript.GetSymbolByIdx(idx);
                if (symbol) {
                    symbol.playAddSpinAnimation();
                    this._remainTimes++;
                    this.updateRemainTimes();
                    this.add_spin_spine.active = true;
                    this.add_spin_spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                    await cc.vv.gameData.awaitTime(0.5);
                    this.add_spin_spine.active = false;
                }
            }
        }

        for (let i = 0; i < this._subGameData.idxs.length; i++) {
            let idx = this._subGameData.idxs[i];
            let symbol = this._slotsScript.GetSymbolByIdx(idx);
            let newInfo = collectGame.gameInfo.items[idx - 1];
            if (!symbol) {
                continue;
            }

            let coin = 0;
            let num = 0;
            for (let j = 0; j < collectGame.gameInfo.items.length; j++) {
                let item = collectGame.gameInfo.items[j];
                if (!item.empty && ((j + 1) !== idx) && item.type === 1) {
                    let startSymbol = this._slotsScript.GetSymbolByIdx(j + 1);
                    if (startSymbol) {
                        coin += item.coin;
                        num++;
                        if (num > 6) {
                            num = 6;
                        }
                        if (newInfo.type !== 3) {
                            Global.SlotsSoundMgr.playEffect("scatr_red" + num);
                        } else {
                            if (item.type === 2 || item.type === 3) {
                                Global.SlotsSoundMgr.playEffect("scatr_yellowgreen");
                            } else {
                                Global.SlotsSoundMgr.playEffect("scatr_red" + num);
                            }
                        }

                        let fly_circle = cc.instantiate(cc.find("safe_node/fly_circle", this.node));
                        fly_circle.active = true;
                        fly_circle.parent = safe_node;
                        let startPos = startSymbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = safe_node.convertToNodeSpaceAR(startPos);
                        fly_circle.position = startPos;
                        let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = safe_node.convertToNodeSpaceAR(endPos);
                        cc.tween(fly_circle)
                            .to(0.5, {position: endPos})
                            .call(()=>{
                                symbol.showBonusCoin(coin);
                                let scatter_up = cc.instantiate(cc.find("scatter_up", safe_node));
                                scatter_up.active = true;
                                scatter_up.parent = safe_node;
                                scatter_up.position = endPos;
                                scatter_up.getComponent(sp.Skeleton).setAnimation(0, "Scatter_up", false);
                                scatter_up.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                    scatter_up.removeFromParent();
                                });
                            })
                            .removeSelf()
                            .start();
                        await cc.vv.gameData.awaitTime(0.6);
                    }
                }
            }

            for (let j = 0; j < collectGame.gameInfo.items.length; j++) {
                let item = collectGame.gameInfo.items[j];
                if (!item.empty && ((j + 1) !== idx) && newInfo.type === 3 && (item.type === 2 || item.type === 3)) {
                    let startSymbol = this._slotsScript.GetSymbolByIdx(j + 1);
                    if (startSymbol) {
                        coin += item.coin;
                        num++;
                        if (num > 6) {
                            num = 6;
                        }
                        if (newInfo.type !== 3) {
                            Global.SlotsSoundMgr.playEffect("scatr_red" + num);
                        } else {
                            if (item.type === 2 || item.type === 3) {
                                Global.SlotsSoundMgr.playEffect("scatr_yellowgreen");
                            } else {
                                Global.SlotsSoundMgr.playEffect("scatr_red" + num);
                            }
                        }

                        let fly_circle = cc.instantiate(cc.find("safe_node/fly_circle", this.node));
                        fly_circle.active = true;
                        fly_circle.parent = safe_node;
                        let startPos = startSymbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = safe_node.convertToNodeSpaceAR(startPos);
                        fly_circle.position = startPos;
                        let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = safe_node.convertToNodeSpaceAR(endPos);
                        cc.tween(fly_circle)
                            .to(0.5, {position: endPos})
                            .call(()=>{
                                symbol.showBonusCoin(coin);
                                let scatter_up = cc.instantiate(cc.find("scatter_up", safe_node));
                                scatter_up.active = true;
                                scatter_up.parent = safe_node;
                                scatter_up.position = endPos;
                                scatter_up.getComponent(sp.Skeleton).setAnimation(0, "Scatter_up", false);
                                scatter_up.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                    scatter_up.removeFromParent();
                                });
                            })
                            .removeSelf()
                            .start();
                        await cc.vv.gameData.awaitTime(0.6);
                    }
                }
            }
        }

        this._greenCoin = collectGame.gameInfo.fullCoin;
        this.updateCoin();

        await cc.vv.gameData.awaitTime(0.5);

        if (collectGame.gameInfo.isEnd) {
            Global.SlotsSoundMgr.playEffect("bgbgmend");

            this.bonus_win.active = true;
            this.remain_times.parent.active = false;
            this.gold_coin.parent.active = false;
            this.green_coin.parent.active = false;


            this.bonus_win_coin.getComponent(cc.Label).string = "";
            let coin = 0;
            for (let i = 0; i < collectGame.gameInfo.items.length; i++) {
                let item = collectGame.gameInfo.items[i];
                if (!item.empty && item.type !== 4) {
                    Global.SlotsSoundMgr.playEffect("bgwin");
                    coin += item.coin;
                    let symbol = this._slotsScript.GetSymbolByIdx(i + 1);
                    if (symbol) {
                        symbol.playBonusWinAnimation();
                        let particle = cc.instantiate(cc.find("particle_dian", safe_node));
                        particle.active = true;
                        particle.parent = safe_node;
                        let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                        startPos = safe_node.convertToNodeSpaceAR(startPos);
                        particle.position = startPos;
                        let endPos = this.bonus_win_coin.convertToWorldSpaceAR(cc.v2(0, 0));
                        endPos = safe_node.convertToNodeSpaceAR(endPos);
                        cc.tween(particle)
                            .to(0.5, {position: endPos})
                            .call(()=>{
                                this.bonus_win_coin.getComponent(cc.Label).string = Global.FormatNumToComma(coin);
                                this.bonus_win_spine.active = true;
                                this.bonus_win_spine.getComponent(sp.Skeleton).setAnimation(0, "jiesuan_glow", false);
                                this.bonus_win_spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                    this.bonus_win_spine.getComponent(sp.Skeleton).setCompleteListener(null);
                                    this.bonus_win_spine.active = false;
                                });
                            })
                            .removeSelf()
                            .start();

                        await cc.vv.gameData.awaitTime(0.7);
                    }
                }
            }

            await this.popBonusResultDialog();

            this.exitBonusGame();

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            cc.vv.gameData.AddCoin(collectGame.gameInfo.winCoin);
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(collectGame.gameInfo.winCoin, collectGame.gameInfo.winCoin, true, ()=>{
                    if(this._exitCallBack){
                        this._exitCallBack();
                    }
                    cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                });
        } else {
            this.reqSpin();
        }
    },

    addCoinNum() {
        this._coinNum++;
        this.coin_num.getComponent(cc.Label).string = this._coinNum;
    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },

    getMaxReelIdx(type, col){
        let reelList = this._slotsScript.getLastStopReel();
        return reelList[col];
    },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        return this._slotsScript.GetLastStopReelIdx();
    },

    // 发送下一次旋转请求
    async reqSpin(){
        this._subGameData = null;
        this._remainTimes--;
        this.updateRemainTimes();
        cc.vv.gameData.setScatterNumInBonusGame(0);
        this._slotsScript.StartMove(cc.vv.gameData.getDeskInfo().collectGame.gameInfo.items);
        let reqdata = {rtype:2};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data;
            cc.vv.gameData.setCollectGame(result.data.collectGame);

            this._slotsScript.setSpinResult(result.data.collectGame);
        }
    },
});