/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    StartMove: function () {
        this._super();
    },

    //显示随机符号
    ShowRandomSymbol: function () {
        this._super();
        if (!cc.vv.gameData.IsBonusGame()) {
            cc.find("free_coin", this.node).active = false;
            cc.find("times", this.node).active = false;
            this.showCoin();
        }
    },

    ShowById(id, data) {
        this._super(id, data);
        if (id === cc.vv.gameData.getGameCfg().scatterId) {
            if (cc.vv.gameData.isInFreeGame()) {
                cc.find("coin", this.node).active = false;
                this._showNode.getComponent("ImgSwitchCmp").setIndex(1);
            } else if (cc.vv.gameData.getCollectGame().state !== 1) {
                this._showNode.getComponent("ImgSwitchCmp").setIndex(data ? data.type - 1 : 1);
            } else {
                this._showNode.getComponent("ImgSwitchCmp").setIndex(0);
            }
        }

        this.showCoin();
    },

    //设置_symbolIdx 行序号
    SetSymbolIdx: function (idx) {
        this._super(idx);
    },

    GetSymbolIdx() {
        return this._symbolIdx;
    },

    showCoin() {
        let coin = cc.find("coin", this.node);
        if (cc.vv.gameData.isInFreeGame() || cc.vv.gameData.IsBonusGame()) {
            if (coin) {
                coin.active = false;
            }
            return;
        }

        if (coin && this._id === cc.vv.gameData.getGameCfg().scatterId) {
            if (this._data) {
                if (this._data.coin > 0) {
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);
                }
            } else {
                coin.active = true;
                let randomRate = [0.25, 0.5, 0.75, 1, 2, 5, 10];
                let randomCoin = cc.vv.gameData.GetTotalBet() * randomRate[Math.floor(Math.random() * randomRate.length)];
                coin.getComponent(cc.Label).string = Global.formatNumShort(randomCoin, 0);
            }
        } else {
            coin.active = false;
        }
    },

    playFreeStopAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            this._state = "stop";
            if (this._showNode) {
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
            this._showNode.active = true

            this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = this._showNode.getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, "Scatter_yellow_down", false)
            }

        }
    },

    playBonusStopAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            this._state = "stop";
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true

            let animationName = "Scatter_yellow_down";
            if (this._data && this._data.type === 3) {
                animationName = "Scatter_green_down";
            }

            aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, animationName, false);
            }

        }
    },

    playBonusWinAnimation() {
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true

            let animationName = "Scatter_red_win";
            if (this._data && this._data.type === 2) {
                animationName = "Scatter_yellow_win";
            } else if (this._data && this._data.type === 3) {
                animationName = "Scatter_green_win";
            }
            aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, animationName, true);
            }
        }
    },

    showBonusCoin(coins) {
        let aniNode = this.setAnimationToTop(true)
        let coin = cc.find("free_coin", aniNode);
        coin.active = true;
        coin.getComponent(cc.Label).string = Global.formatNumShort(coins, 0);
    },

    playFreeAppearAnimation() {
        let aniNode = this.setAnimationToTop(true)
        let cfg = cc.vv.gameData.getGameCfg();
        let topShowNode = cc.find(cfg.symbol[this._id].win_node, aniNode)
        let jiesuan = cc.find("jiesuan", topShowNode);
        if (jiesuan) {
            jiesuan.active = true;
            jiesuan.getComponent(sp.Skeleton).setAnimation(0, "Scatter_yellow_jiesuan", false);
        }
        let nodeSp = topShowNode.getComponent(sp.Skeleton)
        if (nodeSp) {
            nodeSp.setAnimation(0, "Scatter_yellow_appear", false);

            cc.tween(this.node)
                .delay(0.3)
                .call(() => {
                    jiesuan.active = false;
                    let free_coin = cc.find("free_coin", aniNode);
                    free_coin.active = true;
                    free_coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);
                    free_coin.scale = 0;
                    cc.tween(free_coin)
                        .to(0.2, {scale: 1}, {easing: "backOut"})
                        .start();

                    if (this._data.freeCnt && this._data.freeCnt > 0) {
                        let times = cc.find("times", aniNode);
                        times.active = true;
                        times.scale = 0;
                        cc.tween(times)
                            .to(0.2, {scale: 1}, {easing: "backOut"})
                            .start();
                    }
                })

                .start();
        }
    },

    playFreeWinAnimation() {
        let aniNode = this.setAnimationToTop(true)
        let topShowNode = cc.find(cc.vv.gameData.getGameCfg().symbol[this._id].win_node, aniNode)
        let nodeSp = topShowNode.getComponent(sp.Skeleton)
        if (nodeSp) {
            nodeSp.setAnimation(0, "Scatter_yellow_win", true);
        }
    },

    playAddSpinAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()

        if (this._showNode) {
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let topShowNode = cc.find("Spin1", aniNode)
        topShowNode.active = true

        aniNode.zIndex = 300 - this._symbolIdx + this._reelIdx * 10;

        let nodeSp = topShowNode.getComponent(sp.Skeleton)
        if (nodeSp) {
            nodeSp.setAnimation(0, "Spin1", false)
        }


    },

    showBonus() {
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true

            let mask = cc.find("mask", aniNode);
            if (mask) {
                mask.active = false;
            }

            let animationName = "Scatter_red_down";
            if (this._data && this._data.type === 2) {
                animationName = "Scatter_yellow_down";
            } else if (this._data && this._data.type === 3) {
                animationName = "Scatter_green_down";
            }
            aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, animationName, false);
                let coin = cc.find("free_coin", aniNode);
                if (this._data && this._data.type === 1) {
                    coin = cc.find("coin", aniNode);
                }
                coin.active = true;
                coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);
            }
        }
    },

    playBonusAppearAnimation() {
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            aniNode.scale = 0;
            cc.tween(aniNode)
                .to(0.2, {scale: 1})
                .start();
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true
            let mask = cc.find("mask", aniNode);
            if (mask) {
                mask.active = false;
            }

            aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
            let nodeSp = topShowNode.getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, "Scatter_red_appear", false)
            }

            let coin = cc.find("coin", aniNode);
            coin.active = true;

            coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);

            cc.tween(coin)
                .to(0.2, {scale: 1}, {easing: "backOut"})
                .start();
        }
    },
});